export const EXPO_TEMPLATE_FILES: Record<string, Record<string, string>> = {
  "expo-grocery": {
    "App.tsx": "import { useState } from \"react\";\nimport { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { StatusBar } from \"expo-status-bar\";\nimport { SafeAreaProvider } from \"react-native-safe-area-context\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { TabBar, type TabId } from \"./src/components/TabBar\";\nimport { ShopScreen } from \"./src/screens/ShopScreen\";\nimport { CartScreen } from \"./src/screens/CartScreen\";\nimport { AccountScreen } from \"./src/screens/AccountScreen\";\nimport { cartTotals, setQuantity, type Cart } from \"./src/cart\";\nimport { money } from \"./src/data\";\nimport { colors, radius, space } from \"./src/theme\";\n\nexport default function App() {\n  const [tab, setTab] = useState<TabId>(\"shop\");\n  const [cart, setCart] = useState<Cart>({ p2: 1, p4: 1 });\n  const totals = cartTotals(cart);\n  const onQuantity = (id: string, qty: number) => setCart((c) => setQuantity(c, id, qty));\n\n  return (\n    <SafeAreaProvider>\n      <View style={styles.root}>\n        <View style={styles.screen}>\n          {tab === \"shop\" ? <ShopScreen cart={cart} onQuantity={onQuantity} /> : tab === \"cart\" ? <CartScreen cart={cart} onQuantity={onQuantity} onShop={() => setTab(\"shop\")} /> : <AccountScreen />}\n          {tab === \"shop\" && totals.items > 0 ? (\n            <Pressable onPress={() => setTab(\"cart\")} accessibilityRole=\"button\" style={({ pressed }) => [styles.cartBar, pressed && { opacity: 0.9 }]}>\n              <View style={styles.cartCount}>\n                <Text style={styles.cartCountText}>{totals.items}</Text>\n              </View>\n              <Text style={styles.cartLabel}>View cart</Text>\n              <Text style={styles.cartTotal}>{money(totals.subtotal)}</Text>\n              <Ionicons name=\"chevron-forward\" size={18} color=\"#ffffff\" />\n            </Pressable>\n          ) : null}\n        </View>\n        <TabBar active={tab} onChange={setTab} cartCount={totals.items} />\n      </View>\n      <StatusBar style=\"dark\" />\n    </SafeAreaProvider>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1, backgroundColor: colors.background },\n  screen: { flex: 1 },\n  cartBar: {\n    position: \"absolute\",\n    left: space.lg,\n    right: space.lg,\n    bottom: space.lg,\n    flexDirection: \"row\",\n    alignItems: \"center\",\n    gap: space.md,\n    backgroundColor: colors.text,\n    borderRadius: radius.pill,\n    paddingVertical: space.md,\n    paddingHorizontal: space.lg,\n    boxShadow: \"0px 6px 16px rgba(0, 0, 0, 0.18)\",\n  },\n  cartCount: { width: 26, height: 26, borderRadius: 13, backgroundColor: colors.highlight, alignItems: \"center\", justifyContent: \"center\" },\n  cartCountText: { fontSize: 13, fontWeight: \"700\", color: colors.text },\n  cartLabel: { flex: 1, color: \"#ffffff\", fontSize: 16, fontWeight: \"600\" },\n  cartTotal: { color: \"#ffffff\", fontSize: 16, fontWeight: \"700\" },\n});\n",
    "src/cart.ts": "import { PRODUCTS, type Product } from \"./data\";\n\n/** Quantities by product id. */\nexport type Cart = Record<string, number>;\n\nexport function setQuantity(cart: Cart, id: string, qty: number): Cart {\n  const next = { ...cart };\n  if (qty <= 0) delete next[id];\n  else next[id] = qty;\n  return next;\n}\n\nexport function cartLines(cart: Cart): { product: Product; qty: number }[] {\n  return PRODUCTS.filter((p) => cart[p.id]).map((product) => ({ product, qty: cart[product.id] }));\n}\n\nexport function cartTotals(cart: Cart) {\n  const lines = cartLines(cart);\n  const items = lines.reduce((n, l) => n + l.qty, 0);\n  const subtotal = lines.reduce((n, l) => n + l.qty * l.product.price, 0);\n  return { items, subtotal };\n}\n",
    "src/components/ProductCard.tsx": "import { StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { money, type Product } from \"../data\";\nimport { colors, radius, space } from \"../theme\";\nimport { Stepper } from \"./Stepper\";\n\nexport function ProductCard({ product, qty, onChange }: { product: Product; qty: number; onChange: (qty: number) => void }) {\n  return (\n    <View style={styles.card}>\n      <View style={[styles.tile, { backgroundColor: product.tint }]}>\n        <Ionicons name={product.icon} size={44} color={colors.text} style={{ opacity: 0.75 }} />\n      </View>\n      <View style={styles.info}>\n        <Text style={styles.name} numberOfLines={2}>\n          {product.name}\n        </Text>\n        <Text style={styles.unit}>{product.unit}</Text>\n      </View>\n      <View style={styles.footer}>\n        <Text style={styles.price}>{money(product.price)}</Text>\n        <Stepper name={product.name} qty={qty} onChange={onChange} />\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  card: { flex: 1, gap: space.sm },\n  tile: { aspectRatio: 1.2, borderRadius: radius.md, alignItems: \"center\", justifyContent: \"center\" },\n  info: { gap: 2, minHeight: 44 },\n  name: { fontSize: 15, fontWeight: \"600\", color: colors.text },\n  unit: { fontSize: 13, color: colors.muted },\n  footer: { flexDirection: \"row\", alignItems: \"center\", justifyContent: \"space-between\" },\n  price: { fontSize: 16, fontWeight: \"700\", color: colors.text },\n});\n",
    "src/components/Stepper.tsx": "import { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { colors, radius } from \"../theme\";\n\n/** \"+\" when the item is not in the cart, \"− 2 +\" once it is. */\nexport function Stepper({ name, qty, onChange, compact }: { name: string; qty: number; onChange: (qty: number) => void; compact?: boolean }) {\n  if (qty === 0) {\n    return (\n      <Pressable onPress={() => onChange(1)} accessibilityRole=\"button\" accessibilityLabel={`Add ${name} to cart`} hitSlop={6} style={({ pressed }) => [styles.add, pressed && { opacity: 0.8 }]}>\n        <Ionicons name=\"add\" size={20} color=\"#ffffff\" />\n      </Pressable>\n    );\n  }\n  return (\n    <View style={[styles.stepper, compact && styles.compact]}>\n      <Pressable onPress={() => onChange(qty - 1)} accessibilityRole=\"button\" accessibilityLabel={`Remove one ${name}`} hitSlop={6} style={styles.step}>\n        <Ionicons name={qty === 1 ? \"trash-outline\" : \"remove\"} size={16} color=\"#ffffff\" />\n      </Pressable>\n      <Text style={styles.qty} accessibilityLabel={`${qty} in cart`}>\n        {qty}\n      </Text>\n      <Pressable onPress={() => onChange(qty + 1)} accessibilityRole=\"button\" accessibilityLabel={`Add one more ${name}`} hitSlop={6} style={styles.step}>\n        <Ionicons name=\"add\" size={16} color=\"#ffffff\" />\n      </Pressable>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  add: { width: 34, height: 34, borderRadius: 17, backgroundColor: colors.accent, alignItems: \"center\", justifyContent: \"center\" },\n  stepper: { flexDirection: \"row\", alignItems: \"center\", backgroundColor: colors.accent, borderRadius: radius.pill, height: 34 },\n  compact: { alignSelf: \"flex-start\" },\n  step: { width: 32, height: 34, alignItems: \"center\", justifyContent: \"center\" },\n  qty: { minWidth: 18, textAlign: \"center\", color: \"#ffffff\", fontWeight: \"700\", fontSize: 14 },\n});\n",
    "src/components/TabBar.tsx": "import type { ComponentProps } from \"react\";\nimport { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { colors, space } from \"../theme\";\n\nexport type TabId = \"shop\" | \"cart\" | \"account\";\ntype IconName = ComponentProps<typeof Ionicons>[\"name\"];\n\nconst TABS: { id: TabId; label: string; icon: IconName; activeIcon: IconName }[] = [\n  { id: \"shop\", label: \"Shop\", icon: \"storefront-outline\", activeIcon: \"storefront\" },\n  { id: \"cart\", label: \"Cart\", icon: \"basket-outline\", activeIcon: \"basket\" },\n  { id: \"account\", label: \"Account\", icon: \"person-outline\", activeIcon: \"person\" },\n];\n\nexport function TabBar({ active, onChange, cartCount }: { active: TabId; onChange: (t: TabId) => void; cartCount: number }) {\n  const insets = useSafeAreaInsets();\n  return (\n    <View style={[styles.bar, { paddingBottom: Math.max(insets.bottom, space.sm) }]} accessibilityRole=\"tablist\">\n      {TABS.map((t) => {\n        const selected = t.id === active;\n        return (\n          <Pressable key={t.id} onPress={() => onChange(t.id)} accessibilityRole=\"tab\" accessibilityState={{ selected }} accessibilityLabel={t.id === \"cart\" && cartCount ? `Cart, ${cartCount} items` : t.label} style={styles.tab}>\n            <View>\n              <Ionicons name={selected ? t.activeIcon : t.icon} size={24} color={selected ? colors.accent : colors.muted} />\n              {t.id === \"cart\" && cartCount > 0 ? (\n                <View style={styles.badge}>\n                  <Text style={styles.badgeText}>{cartCount}</Text>\n                </View>\n              ) : null}\n            </View>\n            <Text style={[styles.label, selected && { color: colors.accent }]}>{t.label}</Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  bar: { flexDirection: \"row\", backgroundColor: colors.background, borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border, paddingTop: space.sm },\n  tab: { flex: 1, alignItems: \"center\", gap: 2, paddingVertical: space.xs },\n  label: { fontSize: 11, fontWeight: \"600\", color: colors.muted },\n  badge: { position: \"absolute\", top: -4, right: -10, minWidth: 18, height: 18, borderRadius: 9, backgroundColor: colors.highlight, alignItems: \"center\", justifyContent: \"center\", paddingHorizontal: 4 },\n  badgeText: { fontSize: 11, fontWeight: \"700\", color: colors.text },\n});\n",
    "src/data.ts": "/** Catalogue for the store: categories and products. Replace with your own data or an API call. */\nexport type CategoryId = \"all\" | \"fruit\" | \"veg\" | \"dairy\" | \"bakery\" | \"pantry\" | \"drinks\";\n\nexport type Product = {\n  id: string;\n  name: string;\n  unit: string;\n  price: number;\n  category: Exclude<CategoryId, \"all\">;\n  /** Ionicons glyph and tile colour stand in for product photos. */\n  icon: \"nutrition\" | \"leaf\" | \"egg\" | \"pizza\" | \"cafe\" | \"water\" | \"fish\" | \"ice-cream\" | \"flower\" | \"beer\";\n  tint: string;\n};\n\nexport const STORE = { name: \"Greengate Market\", eta: \"25–35 min\", address: \"24 Elm Street\", freeDeliveryOver: 35 };\n\nexport const CATEGORIES: { id: CategoryId; label: string }[] = [\n  { id: \"all\", label: \"All\" },\n  { id: \"fruit\", label: \"Fruit\" },\n  { id: \"veg\", label: \"Vegetables\" },\n  { id: \"dairy\", label: \"Dairy & eggs\" },\n  { id: \"bakery\", label: \"Bakery\" },\n  { id: \"pantry\", label: \"Pantry\" },\n  { id: \"drinks\", label: \"Drinks\" },\n];\n\nexport const PRODUCTS: Product[] = [\n  { id: \"p1\", name: \"Honeycrisp apples\", unit: \"1 kg bag\", price: 4.49, category: \"fruit\", icon: \"nutrition\", tint: \"#fde2e1\" },\n  { id: \"p2\", name: \"Baby spinach\", unit: \"200 g\", price: 2.79, category: \"veg\", icon: \"leaf\", tint: \"#dcf3e3\" },\n  { id: \"p3\", name: \"Free-range eggs\", unit: \"Dozen\", price: 5.25, category: \"dairy\", icon: \"egg\", tint: \"#fbf1d9\" },\n  { id: \"p4\", name: \"Stone-baked pizza bases\", unit: \"2 × 250 g\", price: 6.1, category: \"bakery\", icon: \"pizza\", tint: \"#f4e6d7\" },\n  { id: \"p5\", name: \"Whole bean coffee\", unit: \"340 g\", price: 11.9, category: \"pantry\", icon: \"cafe\", tint: \"#ece4dc\" },\n  { id: \"p6\", name: \"Sparkling water\", unit: \"6 × 330 ml\", price: 3.99, category: \"drinks\", icon: \"water\", tint: \"#dfeefa\" },\n  { id: \"p7\", name: \"Bananas\", unit: \"Bunch of 6\", price: 1.89, category: \"fruit\", icon: \"nutrition\", tint: \"#fbf3cf\" },\n  { id: \"p8\", name: \"Greek yoghurt\", unit: \"500 g\", price: 3.6, category: \"dairy\", icon: \"ice-cream\", tint: \"#eef0f3\" },\n  { id: \"p9\", name: \"Atlantic salmon\", unit: \"2 fillets\", price: 9.8, category: \"pantry\", icon: \"fish\", tint: \"#fde4da\" },\n  { id: \"p10\", name: \"Tulip bunch\", unit: \"10 stems\", price: 7.5, category: \"veg\", icon: \"flower\", tint: \"#fbe1ec\" },\n];\n\nexport function money(n: number) {\n  return `$${n.toFixed(2)}`;\n}\n",
    "src/screens/AccountScreen.tsx": "import type { ComponentProps } from \"react\";\nimport { ScrollView, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { STORE } from \"../data\";\nimport { colors, radius, space } from \"../theme\";\n\ntype Item = { icon: ComponentProps<typeof Ionicons>[\"name\"]; label: string; value: string };\n\nconst DETAILS: Item[] = [\n  { icon: \"location-outline\", label: \"Delivery address\", value: STORE.address },\n  { icon: \"card-outline\", label: \"Payment\", value: \"Not set up\" },\n  { icon: \"storefront-outline\", label: \"Store\", value: STORE.name },\n  { icon: \"time-outline\", label: \"Usual delivery\", value: STORE.eta },\n];\n\nexport function AccountScreen() {\n  const insets = useSafeAreaInsets();\n  return (\n    <ScrollView style={styles.screen} contentContainerStyle={[styles.content, { paddingTop: insets.top + space.lg }]}>\n      <Text style={styles.title} accessibilityRole=\"header\">\n        Account\n      </Text>\n      <View style={styles.card}>\n        {DETAILS.map((d, i) => (\n          <View key={d.label} style={[styles.row, i > 0 && styles.divider]}>\n            <Ionicons name={d.icon} size={20} color={colors.accent} />\n            <Text style={styles.label}>{d.label}</Text>\n            <Text style={styles.value}>{d.value}</Text>\n          </View>\n        ))}\n      </View>\n      <Text style={styles.note}>Sign-in, saved addresses and order history are not built yet. Describe them to Codexa to add them.</Text>\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.background },\n  content: { paddingHorizontal: space.lg, paddingBottom: space.xxl, gap: space.lg },\n  title: { fontSize: 28, fontWeight: \"700\", color: colors.text, letterSpacing: -0.5 },\n  card: { backgroundColor: colors.surface, borderRadius: radius.md, paddingHorizontal: space.lg },\n  row: { flexDirection: \"row\", alignItems: \"center\", gap: space.md, paddingVertical: space.lg },\n  divider: { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border },\n  label: { flex: 1, fontSize: 15, color: colors.text },\n  value: { fontSize: 14, color: colors.muted },\n  note: { fontSize: 13, color: colors.muted, textAlign: \"center\", lineHeight: 19 },\n});\n",
    "src/screens/CartScreen.tsx": "import { useState } from \"react\";\nimport { Pressable, ScrollView, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { STORE, money } from \"../data\";\nimport { cartLines, cartTotals, type Cart } from \"../cart\";\nimport { Stepper } from \"../components/Stepper\";\nimport { colors, radius, space } from \"../theme\";\n\nconst DELIVERY_FEE = 3.99;\n\nexport function CartScreen({ cart, onQuantity, onShop }: { cart: Cart; onQuantity: (id: string, qty: number) => void; onShop: () => void }) {\n  const insets = useSafeAreaInsets();\n  const [checkout, setCheckout] = useState(false);\n  const lines = cartLines(cart);\n  const { subtotal } = cartTotals(cart);\n  const delivery = subtotal >= STORE.freeDeliveryOver || subtotal === 0 ? 0 : DELIVERY_FEE;\n\n  return (\n    <ScrollView style={styles.screen} contentContainerStyle={[styles.content, { paddingTop: insets.top + space.lg }]}>\n      <Text style={styles.title} accessibilityRole=\"header\">\n        Your cart\n      </Text>\n      {lines.length === 0 ? (\n        <View style={styles.empty}>\n          <Ionicons name=\"basket-outline\" size={48} color={colors.muted} />\n          <Text style={styles.emptyTitle}>Your cart is empty</Text>\n          <Pressable onPress={onShop} accessibilityRole=\"button\" style={styles.primary}>\n            <Text style={styles.primaryText}>Start shopping</Text>\n          </Pressable>\n        </View>\n      ) : (\n        <>\n          <View style={styles.card}>\n            {lines.map(({ product, qty }, i) => (\n              <View key={product.id} style={[styles.line, i > 0 && styles.divider]}>\n                <View style={[styles.thumb, { backgroundColor: product.tint }]}>\n                  <Ionicons name={product.icon} size={22} color={colors.text} style={{ opacity: 0.75 }} />\n                </View>\n                <View style={{ flex: 1, gap: 2 }}>\n                  <Text style={styles.name}>{product.name}</Text>\n                  <Text style={styles.muted}>{money(product.price * qty)}</Text>\n                </View>\n                <Stepper name={product.name} qty={qty} onChange={(n) => onQuantity(product.id, n)} compact />\n              </View>\n            ))}\n          </View>\n          <View style={styles.card}>\n            <Row label=\"Subtotal\" value={money(subtotal)} />\n            <Row label=\"Delivery\" value={delivery === 0 ? \"Free\" : money(delivery)} />\n            <Row label=\"Total\" value={money(subtotal + delivery)} strong />\n          </View>\n          {delivery > 0 ? <Text style={styles.hint}>Add {money(STORE.freeDeliveryOver - subtotal)} more for free delivery.</Text> : null}\n          <Pressable accessibilityRole=\"button\" style={styles.primary} onPress={() => setCheckout(true)}>\n            <Text style={styles.primaryText}>Go to checkout</Text>\n          </Pressable>\n          {checkout ? (\n            <Text style={styles.hint} accessibilityLiveRegion=\"polite\">\n              Checkout is not connected yet. Ask Codexa to add a payment provider.\n            </Text>\n          ) : null}\n        </>\n      )}\n    </ScrollView>\n  );\n}\n\nfunction Row({ label, value, strong }: { label: string; value: string; strong?: boolean }) {\n  return (\n    <View style={styles.row}>\n      <Text style={[styles.muted, strong && styles.strong]}>{label}</Text>\n      <Text style={[styles.value, strong && styles.strong]}>{value}</Text>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.background },\n  content: { paddingHorizontal: space.lg, paddingBottom: space.xxl, gap: space.lg },\n  title: { fontSize: 28, fontWeight: \"700\", color: colors.text, letterSpacing: -0.5 },\n  card: { backgroundColor: colors.surface, borderRadius: radius.md, padding: space.lg, gap: space.md },\n  line: { flexDirection: \"row\", alignItems: \"center\", gap: space.md },\n  divider: { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border, paddingTop: space.md },\n  thumb: { width: 44, height: 44, borderRadius: radius.sm, alignItems: \"center\", justifyContent: \"center\" },\n  name: { fontSize: 15, fontWeight: \"600\", color: colors.text },\n  muted: { fontSize: 14, color: colors.muted },\n  row: { flexDirection: \"row\", justifyContent: \"space-between\" },\n  value: { fontSize: 14, color: colors.text, fontWeight: \"500\" },\n  strong: { fontSize: 16, fontWeight: \"700\", color: colors.text },\n  hint: { textAlign: \"center\", fontSize: 13, color: colors.muted },\n  primary: { backgroundColor: colors.accent, borderRadius: radius.pill, paddingVertical: space.lg, paddingHorizontal: space.xl, alignItems: \"center\" },\n  primaryText: { color: \"#ffffff\", fontSize: 16, fontWeight: \"700\" },\n  empty: { alignItems: \"center\", gap: space.md, paddingVertical: space.xxl },\n  emptyTitle: { fontSize: 17, fontWeight: \"600\", color: colors.text },\n});\n",
    "src/screens/ShopScreen.tsx": "import { useMemo, useState } from \"react\";\nimport { FlatList, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { CATEGORIES, PRODUCTS, STORE, type CategoryId } from \"../data\";\nimport type { Cart } from \"../cart\";\nimport { ProductCard } from \"../components/ProductCard\";\nimport { colors, radius, space } from \"../theme\";\n\nexport function ShopScreen({ cart, onQuantity }: { cart: Cart; onQuantity: (id: string, qty: number) => void }) {\n  const insets = useSafeAreaInsets();\n  const [category, setCategory] = useState<CategoryId>(\"all\");\n  const [query, setQuery] = useState(\"\");\n\n  const products = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return PRODUCTS.filter((p) => (category === \"all\" || p.category === category) && (!q || p.name.toLowerCase().includes(q)));\n  }, [category, query]);\n\n  const header = (\n    <View style={[styles.header, { paddingTop: insets.top + space.md }]}>\n      <View style={styles.topRow}>\n        <View>\n          <Text style={styles.deliverTo}>Deliver to</Text>\n          <View style={styles.addressRow}>\n            <Text style={styles.address}>{STORE.address}</Text>\n            <Ionicons name=\"chevron-down\" size={16} color={colors.text} />\n          </View>\n        </View>\n        <View style={styles.eta}>\n          <Ionicons name=\"time-outline\" size={14} color={colors.accent} />\n          <Text style={styles.etaText}>{STORE.eta}</Text>\n        </View>\n      </View>\n\n      <View style={styles.search}>\n        <Ionicons name=\"search\" size={18} color={colors.muted} />\n        <TextInput value={query} onChangeText={setQuery} placeholder={`Search ${STORE.name}`} placeholderTextColor={colors.muted} style={styles.searchInput} accessibilityLabel=\"Search products\" />\n      </View>\n\n      <View style={styles.promo}>\n        <View style={{ flex: 1, gap: 4 }}>\n          <Text style={styles.promoTitle}>Free delivery over ${STORE.freeDeliveryOver}</Text>\n          <Text style={styles.promoBody}>Fresh produce from local farms, picked this morning.</Text>\n        </View>\n        <Ionicons name=\"bicycle\" size={40} color={colors.highlight} />\n      </View>\n\n      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips} accessibilityRole=\"tablist\">\n        {CATEGORIES.map((c) => {\n          const active = c.id === category;\n          return (\n            <Pressable key={c.id} onPress={() => setCategory(c.id)} accessibilityRole=\"tab\" accessibilityState={{ selected: active }} style={[styles.chip, active && styles.chipActive]}>\n              <Text style={[styles.chipText, active && styles.chipTextActive]}>{c.label}</Text>\n            </Pressable>\n          );\n        })}\n      </ScrollView>\n      <Text style={styles.sectionTitle}>{category === \"all\" ? \"Popular this week\" : CATEGORIES.find((c) => c.id === category)?.label}</Text>\n    </View>\n  );\n\n  return (\n    <FlatList\n      data={products}\n      keyExtractor={(p) => p.id}\n      numColumns={2}\n      ListHeaderComponent={header}\n      ListEmptyComponent={<Text style={styles.empty}>No products match “{query}”.</Text>}\n      columnWrapperStyle={styles.columns}\n      contentContainerStyle={styles.list}\n      renderItem={({ item }) => <ProductCard product={item} qty={cart[item.id] ?? 0} onChange={(qty) => onQuantity(item.id, qty)} />}\n      style={styles.screen}\n    />\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.background },\n  list: { paddingHorizontal: space.lg, paddingBottom: 120, gap: space.xl },\n  columns: { gap: space.lg },\n  header: { gap: space.lg },\n  topRow: { flexDirection: \"row\", justifyContent: \"space-between\", alignItems: \"center\" },\n  deliverTo: { fontSize: 12, color: colors.muted, fontWeight: \"500\" },\n  addressRow: { flexDirection: \"row\", alignItems: \"center\", gap: 4 },\n  address: { fontSize: 17, fontWeight: \"700\", color: colors.text },\n  eta: { flexDirection: \"row\", alignItems: \"center\", gap: 4, backgroundColor: colors.accentSoft, paddingHorizontal: space.md, paddingVertical: 6, borderRadius: radius.pill },\n  etaText: { fontSize: 13, fontWeight: \"600\", color: colors.accent },\n  search: { flexDirection: \"row\", alignItems: \"center\", gap: space.sm, backgroundColor: colors.surface, borderRadius: radius.md, paddingHorizontal: space.md },\n  searchInput: { flex: 1, paddingVertical: space.md, fontSize: 15, color: colors.text },\n  promo: { flexDirection: \"row\", alignItems: \"center\", gap: space.lg, backgroundColor: colors.accent, borderRadius: radius.lg, padding: space.lg },\n  promoTitle: { color: \"#ffffff\", fontSize: 17, fontWeight: \"700\" },\n  promoBody: { color: \"#cfe3d5\", fontSize: 13, lineHeight: 18 },\n  chips: { gap: space.sm },\n  chip: { paddingHorizontal: space.lg, paddingVertical: space.sm, borderRadius: radius.pill, backgroundColor: colors.surface },\n  chipActive: { backgroundColor: colors.text },\n  chipText: { fontSize: 14, fontWeight: \"600\", color: colors.text },\n  chipTextActive: { color: \"#ffffff\" },\n  sectionTitle: { fontSize: 20, fontWeight: \"700\", color: colors.text, letterSpacing: -0.3 },\n  empty: { textAlign: \"center\", color: colors.muted, paddingVertical: space.xxl },\n});\n",
    "src/theme.ts": "export const colors = {\n  background: \"#ffffff\",\n  surface: \"#f5f6f3\",\n  text: \"#16201a\",\n  muted: \"#66706a\",\n  border: \"#e6e8e3\",\n  accent: \"#166534\",\n  accentSoft: \"#e5f0e8\",\n  highlight: \"#f5c451\",\n};\n\nexport const space = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 };\nexport const radius = { sm: 8, md: 14, lg: 20, pill: 999 };\n",
  },
  "expo-habits": {
    "App.tsx": "import { useState } from \"react\";\nimport { ScrollView, StyleSheet, Text, View } from \"react-native\";\nimport { StatusBar } from \"expo-status-bar\";\nimport { SafeAreaProvider, useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { HabitRow } from \"./src/components/HabitRow\";\nimport { NewHabit } from \"./src/components/NewHabit\";\nimport { WeekStrip } from \"./src/components/WeekStrip\";\nimport { dayKey, sampleHabits, type Habit, type HabitIcon } from \"./src/habits\";\nimport { useStoredState } from \"./src/useStoredState\";\nimport { colors, radius, space } from \"./src/theme\";\n\nexport default function App() {\n  return (\n    <SafeAreaProvider>\n      <HabitsScreen />\n      <StatusBar style=\"dark\" />\n    </SafeAreaProvider>\n  );\n}\n\nfunction HabitsScreen() {\n  const insets = useSafeAreaInsets();\n  const [habits, setHabits] = useStoredState<Habit[]>(\"habits-v1\", sampleHabits);\n  const [selected, setSelected] = useState(() => new Date());\n  const key = dayKey(selected);\n  const doneCount = habits.filter((h) => h.done.includes(key)).length;\n  const pct = habits.length ? Math.round((doneCount / habits.length) * 100) : 0;\n  const isToday = key === dayKey(new Date());\n\n  const toggle = (id: string) =>\n    setHabits((list) => list.map((h) => (h.id !== id ? h : { ...h, done: h.done.includes(key) ? h.done.filter((d) => d !== key) : [...h.done, key] })));\n  const remove = (id: string) => setHabits((list) => list.filter((h) => h.id !== id));\n  const add = (name: string, icon: HabitIcon) => setHabits((list) => [...list, { id: `h${Date.now()}`, name, icon, goal: \"Every day\", done: [] }]);\n\n  return (\n    <ScrollView style={styles.scroll} contentContainerStyle={[styles.content, { paddingTop: insets.top + space.lg, paddingBottom: insets.bottom + space.xxl }]}>\n      <View>\n        <Text style={styles.date}>{selected.toLocaleDateString(\"en-US\", { weekday: \"long\", month: \"long\", day: \"numeric\" })}</Text>\n        <Text style={styles.title} accessibilityRole=\"header\">\n          {isToday ? \"Today\" : \"Looking back\"}\n        </Text>\n      </View>\n\n      <View style={styles.progress} accessibilityLabel={`${doneCount} of ${habits.length} habits done`}>\n        <View style={styles.progressText}>\n          <Text style={styles.progressBig}>{pct}%</Text>\n          <Text style={styles.progressSmall}>\n            {doneCount} of {habits.length} habits done\n          </Text>\n        </View>\n        <View style={styles.track}>\n          <View style={[styles.fill, { width: `${pct}%` }]} />\n        </View>\n      </View>\n\n      <WeekStrip selected={selected} onSelect={setSelected} habits={habits} />\n\n      <View style={styles.list}>\n        {habits.map((h) => (\n          <HabitRow key={h.id} habit={h} day={key} onToggle={() => toggle(h.id)} onRemove={() => remove(h.id)} />\n        ))}\n        {habits.length === 0 ? <Text style={styles.empty}>No habits yet. Add the first one below.</Text> : null}\n      </View>\n\n      <NewHabit onAdd={add} />\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  scroll: { flex: 1, backgroundColor: colors.background },\n  content: { paddingHorizontal: space.lg, gap: space.xl },\n  date: { fontSize: 14, color: colors.muted, fontWeight: \"500\" },\n  title: { fontSize: 32, fontWeight: \"700\", color: colors.text, letterSpacing: -0.6 },\n  progress: { backgroundColor: colors.accent, borderRadius: radius.lg, padding: space.xl, gap: space.md },\n  progressText: { flexDirection: \"row\", alignItems: \"baseline\", justifyContent: \"space-between\" },\n  progressBig: { fontSize: 40, fontWeight: \"700\", color: colors.accentText, letterSpacing: -1 },\n  progressSmall: { fontSize: 14, color: \"#c9e7d8\", fontWeight: \"500\" },\n  track: { height: 8, borderRadius: radius.pill, backgroundColor: \"rgba(255,255,255,0.22)\", overflow: \"hidden\" },\n  fill: { height: 8, borderRadius: radius.pill, backgroundColor: \"#ffffff\" },\n  list: { gap: space.sm },\n  empty: { textAlign: \"center\", color: colors.muted, paddingVertical: space.xl },\n});\n",
    "src/components/HabitRow.tsx": "import { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { dayKey, lastSevenDays, streak, type Habit } from \"../habits\";\nimport { colors, radius, space } from \"../theme\";\n\n/** One habit: tap the circle to check it off for the selected day, long-press the row to delete it. */\nexport function HabitRow({ habit, day, onToggle, onRemove }: { habit: Habit; day: string; onToggle: () => void; onRemove: () => void }) {\n  const done = habit.done.includes(day);\n  const days = streak(habit);\n  return (\n    <Pressable onLongPress={onRemove} accessibilityHint=\"Long-press to delete this habit\" style={styles.card}>\n      <View style={styles.icon}>\n        <Ionicons name={habit.icon} size={20} color={colors.accent} />\n      </View>\n      <View style={styles.body}>\n        <Text style={styles.name} numberOfLines={1}>\n          {habit.name}\n        </Text>\n        <View style={styles.meta}>\n          <View style={styles.week} accessibilityElementsHidden importantForAccessibility=\"no-hide-descendants\">\n            {lastSevenDays().map((d) => (\n              <View key={d.toISOString()} style={[styles.cell, habit.done.includes(dayKey(d)) && styles.cellOn]} />\n            ))}\n          </View>\n          <Text style={styles.streak}>{days > 0 ? `${days}-day streak` : habit.goal}</Text>\n        </View>\n      </View>\n      <Pressable\n        onPress={onToggle}\n        accessibilityRole=\"checkbox\"\n        accessibilityState={{ checked: done }}\n        accessibilityLabel={`Mark ${habit.name} as done`}\n        hitSlop={8}\n        style={({ pressed }) => [styles.check, done && styles.checkOn, pressed && { transform: [{ scale: 0.92 }] }]}\n      >\n        {done ? <Ionicons name=\"checkmark\" size={20} color=\"#ffffff\" /> : null}\n      </Pressable>\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  card: { flexDirection: \"row\", alignItems: \"center\", gap: space.md, backgroundColor: colors.surface, borderRadius: radius.md, padding: space.md, borderWidth: StyleSheet.hairlineWidth, borderColor: colors.border },\n  icon: { width: 42, height: 42, borderRadius: radius.sm, backgroundColor: colors.accentSoft, alignItems: \"center\", justifyContent: \"center\" },\n  body: { flex: 1, gap: 6 },\n  name: { fontSize: 16, fontWeight: \"600\", color: colors.text },\n  meta: { flexDirection: \"row\", alignItems: \"center\", gap: space.sm },\n  week: { flexDirection: \"row\", gap: 3 },\n  cell: { width: 8, height: 8, borderRadius: 2, backgroundColor: colors.border },\n  cellOn: { backgroundColor: colors.accent },\n  streak: { fontSize: 12, color: colors.muted, fontWeight: \"500\" },\n  check: { width: 36, height: 36, borderRadius: 18, borderWidth: 2, borderColor: colors.border, alignItems: \"center\", justifyContent: \"center\" },\n  checkOn: { backgroundColor: colors.accent, borderColor: colors.accent },\n});\n",
    "src/components/NewHabit.tsx": "import { useState } from \"react\";\nimport { Pressable, StyleSheet, Text, TextInput, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { ICONS, type HabitIcon } from \"../habits\";\nimport { colors, radius, space } from \"../theme\";\n\n/** A collapsed \"New habit\" button that opens into a small form (name + icon). */\nexport function NewHabit({ onAdd }: { onAdd: (name: string, icon: HabitIcon) => void }) {\n  const [open, setOpen] = useState(false);\n  const [name, setName] = useState(\"\");\n  const [icon, setIcon] = useState<HabitIcon>(\"leaf\");\n\n  const submit = () => {\n    const n = name.trim();\n    if (!n) return;\n    onAdd(n, icon);\n    setName(\"\");\n    setOpen(false);\n  };\n\n  if (!open) {\n    return (\n      <Pressable onPress={() => setOpen(true)} accessibilityRole=\"button\" style={({ pressed }) => [styles.add, pressed && { opacity: 0.7 }]}>\n        <Ionicons name=\"add\" size={20} color={colors.accent} />\n        <Text style={styles.addText}>New habit</Text>\n      </Pressable>\n    );\n  }\n\n  return (\n    <View style={styles.form}>\n      <Text style={styles.label}>Name</Text>\n      <TextInput value={name} onChangeText={setName} placeholder=\"e.g. Stretch for 5 minutes\" placeholderTextColor={colors.faint} style={styles.input} autoFocus onSubmitEditing={submit} returnKeyType=\"done\" accessibilityLabel=\"Habit name\" />\n      <Text style={styles.label}>Icon</Text>\n      <View style={styles.icons}>\n        {ICONS.map((i) => (\n          <Pressable key={i} onPress={() => setIcon(i)} accessibilityRole=\"radio\" accessibilityState={{ checked: icon === i }} accessibilityLabel={i} style={[styles.iconChoice, icon === i && styles.iconChoiceOn]}>\n            <Ionicons name={i} size={18} color={icon === i ? \"#ffffff\" : colors.muted} />\n          </Pressable>\n        ))}\n      </View>\n      <View style={styles.actions}>\n        <Pressable onPress={() => setOpen(false)} accessibilityRole=\"button\" style={styles.secondary}>\n          <Text style={styles.secondaryText}>Cancel</Text>\n        </Pressable>\n        <Pressable onPress={submit} accessibilityRole=\"button\" disabled={!name.trim()} style={[styles.primary, !name.trim() && { opacity: 0.5 }]}>\n          <Text style={styles.primaryText}>Add habit</Text>\n        </Pressable>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  add: { flexDirection: \"row\", alignItems: \"center\", justifyContent: \"center\", gap: space.xs, paddingVertical: space.md, borderRadius: radius.md, borderWidth: 1, borderStyle: \"dashed\", borderColor: colors.faint },\n  addText: { fontSize: 15, fontWeight: \"600\", color: colors.accent },\n  form: { backgroundColor: colors.surface, borderRadius: radius.md, padding: space.lg, gap: space.sm },\n  label: { fontSize: 13, fontWeight: \"600\", color: colors.muted },\n  input: { borderWidth: 1, borderColor: colors.border, borderRadius: radius.sm, paddingHorizontal: space.md, paddingVertical: space.md, fontSize: 15, color: colors.text },\n  icons: { flexDirection: \"row\", flexWrap: \"wrap\", gap: space.sm },\n  iconChoice: { width: 38, height: 38, borderRadius: radius.sm, backgroundColor: colors.background, alignItems: \"center\", justifyContent: \"center\" },\n  iconChoiceOn: { backgroundColor: colors.accent },\n  actions: { flexDirection: \"row\", justifyContent: \"flex-end\", gap: space.sm, marginTop: space.sm },\n  secondary: { paddingHorizontal: space.lg, paddingVertical: space.md, borderRadius: radius.sm },\n  secondaryText: { fontSize: 15, fontWeight: \"600\", color: colors.muted },\n  primary: { paddingHorizontal: space.lg, paddingVertical: space.md, borderRadius: radius.sm, backgroundColor: colors.accent },\n  primaryText: { fontSize: 15, fontWeight: \"600\", color: \"#ffffff\" },\n});\n",
    "src/components/WeekStrip.tsx": "import { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { dayKey, lastSevenDays, type Habit } from \"../habits\";\nimport { colors, radius, space } from \"../theme\";\n\n/** The last seven days; tap one to check habits off for that day. A dot marks days with everything done. */\nexport function WeekStrip({ selected, onSelect, habits }: { selected: Date; onSelect: (d: Date) => void; habits: Habit[] }) {\n  const selectedKey = dayKey(selected);\n  return (\n    <View style={styles.row} accessibilityRole=\"tablist\">\n      {lastSevenDays().map((d) => {\n        const key = dayKey(d);\n        const active = key === selectedKey;\n        const complete = habits.length > 0 && habits.every((h) => h.done.includes(key));\n        return (\n          <Pressable\n            key={key}\n            onPress={() => onSelect(d)}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected: active }}\n            accessibilityLabel={d.toLocaleDateString(\"en-US\", { weekday: \"long\", month: \"short\", day: \"numeric\" })}\n            style={[styles.day, active && styles.dayActive]}\n          >\n            <Text style={[styles.weekday, active && styles.textActive]}>{d.toLocaleDateString(\"en-US\", { weekday: \"narrow\" })}</Text>\n            <Text style={[styles.date, active && styles.textActive]}>{d.getDate()}</Text>\n            <View style={[styles.dot, complete && (active ? styles.dotOnActive : styles.dotOn)]} />\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  row: { flexDirection: \"row\", gap: space.xs },\n  day: { flex: 1, alignItems: \"center\", gap: 2, paddingVertical: space.sm, borderRadius: radius.md, backgroundColor: colors.surface },\n  dayActive: { backgroundColor: colors.text },\n  weekday: { fontSize: 12, color: colors.muted, fontWeight: \"500\" },\n  date: { fontSize: 17, fontWeight: \"700\", color: colors.text },\n  textActive: { color: \"#ffffff\" },\n  dot: { width: 5, height: 5, borderRadius: 3, marginTop: 2, backgroundColor: \"transparent\" },\n  dotOn: { backgroundColor: colors.accent },\n  dotOnActive: { backgroundColor: \"#6ee7b7\" },\n});\n",
    "src/habits.ts": "/** Habit data, date helpers and the sample habits a new install starts with. */\nexport type Habit = { id: string; name: string; icon: HabitIcon; goal: string; done: string[] };\n\nexport type HabitIcon = \"water\" | \"walk\" | \"book\" | \"leaf\" | \"barbell\" | \"moon\" | \"bicycle\" | \"musical-notes\";\nexport const ICONS: HabitIcon[] = [\"water\", \"walk\", \"book\", \"leaf\", \"barbell\", \"moon\", \"bicycle\", \"musical-notes\"];\n\n/** YYYY-MM-DD in local time. */\nexport function dayKey(d: Date): string {\n  const m = String(d.getMonth() + 1).padStart(2, \"0\");\n  const day = String(d.getDate()).padStart(2, \"0\");\n  return `${d.getFullYear()}-${m}-${day}`;\n}\n\nexport function addDays(d: Date, n: number): Date {\n  const out = new Date(d);\n  out.setDate(out.getDate() + n);\n  return out;\n}\n\n/** The last seven days, oldest first, ending today. */\nexport function lastSevenDays(today = new Date()): Date[] {\n  return Array.from({ length: 7 }, (_, i) => addDays(today, i - 6));\n}\n\n/** Consecutive days completed, counting back from today (or yesterday if today is still open). */\nexport function streak(habit: Habit, today = new Date()): number {\n  const done = new Set(habit.done);\n  let cursor = done.has(dayKey(today)) ? today : addDays(today, -1);\n  let n = 0;\n  while (done.has(dayKey(cursor))) {\n    n++;\n    cursor = addDays(cursor, -1);\n  }\n  return n;\n}\n\nfunction seed(offsets: number[]): string[] {\n  const today = new Date();\n  return offsets.map((o) => dayKey(addDays(today, -o)));\n}\n\nexport function sampleHabits(): Habit[] {\n  return [\n    { id: \"h1\", name: \"Drink 2 litres of water\", icon: \"water\", goal: \"Every day\", done: seed([1, 2, 3, 4, 5, 6]) },\n    { id: \"h2\", name: \"10-minute walk\", icon: \"walk\", goal: \"Every day\", done: seed([0, 1, 2, 4, 5]) },\n    { id: \"h3\", name: \"Read 20 pages\", icon: \"book\", goal: \"Every day\", done: seed([0, 2, 3, 6]) },\n    { id: \"h4\", name: \"Lights out by 11\", icon: \"moon\", goal: \"Weeknights\", done: seed([1, 3]) },\n  ];\n}\n",
    "src/theme.ts": "/** Colours and spacing for the habit tracker. One accent (green) for progress and actions. */\nexport const colors = {\n  background: \"#f6f7f4\",\n  surface: \"#ffffff\",\n  text: \"#14211a\",\n  muted: \"#5d6b62\",\n  faint: \"#a3ada6\",\n  border: \"#e2e5dc\",\n  accent: \"#047857\",\n  accentSoft: \"#e3f1ea\",\n  accentText: \"#ffffff\",\n};\n\nexport const space = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 };\nexport const radius = { sm: 8, md: 14, lg: 20, pill: 999 };\n",
    "src/useStoredState.ts": "import { useEffect, useRef, useState } from \"react\";\nimport AsyncStorage from \"@react-native-async-storage/async-storage\";\n\n/**\n * useState that is saved with AsyncStorage (device storage on iOS/Android, localStorage on the\n * web). `ready` is false until the saved value has been read.\n */\nexport function useStoredState<T>(key: string, initial: () => T) {\n  const [value, setValue] = useState<T>(initial);\n  const [ready, setReady] = useState(false);\n  const loaded = useRef(false);\n\n  useEffect(() => {\n    let cancelled = false;\n    AsyncStorage.getItem(key)\n      .then((raw) => {\n        if (!cancelled && raw) setValue(JSON.parse(raw) as T);\n      })\n      .catch(() => {})\n      .finally(() => {\n        loaded.current = true;\n        if (!cancelled) setReady(true);\n      });\n    return () => {\n      cancelled = true;\n    };\n  }, [key]);\n\n  useEffect(() => {\n    if (!loaded.current) return;\n    AsyncStorage.setItem(key, JSON.stringify(value)).catch(() => {});\n  }, [key, value]);\n\n  return [value, setValue, ready] as const;\n}\n",
  },
  "expo-notes": {
    "App.tsx": "import { useState } from \"react\";\nimport { StatusBar } from \"expo-status-bar\";\nimport { SafeAreaProvider } from \"react-native-safe-area-context\";\nimport { NotesList } from \"./src/screens/NotesList\";\nimport { NoteEditor } from \"./src/screens/NoteEditor\";\nimport { newNote, sampleNotes, type Note } from \"./src/notes\";\nimport { useStoredState } from \"./src/useStoredState\";\n\n/** Two screens, list and editor, switched with state. Notes persist with AsyncStorage. */\nexport default function App() {\n  const [notes, setNotes] = useStoredState<Note[]>(\"notes-v1\", sampleNotes);\n  const [openId, setOpenId] = useState<string | null>(null);\n  const open = openId ? notes.find((n) => n.id === openId) : undefined;\n\n  const create = () => {\n    const n = newNote();\n    setNotes((list) => [n, ...list]);\n    setOpenId(n.id);\n  };\n  const update = (id: string, patch: Partial<Note>) => setNotes((list) => list.map((n) => (n.id === id ? { ...n, ...patch, updatedAt: Date.now() } : n)));\n  const remove = (id: string) => {\n    setNotes((list) => list.filter((n) => n.id !== id));\n    setOpenId(null);\n  };\n  const back = () => {\n    // Drop a note that was opened but never written in.\n    if (open && !open.title.trim() && !open.body.trim()) setNotes((list) => list.filter((n) => n.id !== open.id));\n    setOpenId(null);\n  };\n\n  return (\n    <SafeAreaProvider>\n      {open ? <NoteEditor note={open} onChange={(p) => update(open.id, p)} onBack={back} onDelete={() => remove(open.id)} /> : <NotesList notes={notes} onOpen={setOpenId} onCreate={create} />}\n      <StatusBar style=\"dark\" />\n    </SafeAreaProvider>\n  );\n}\n",
    "src/notes.ts": "/** Notes data and helpers. Notes are saved on the device with AsyncStorage (see App.tsx). */\nexport type Note = { id: string; title: string; body: string; pinned: boolean; updatedAt: number };\n\nexport function newNote(): Note {\n  return { id: `n${Date.now()}`, title: \"\", body: \"\", pinned: false, updatedAt: Date.now() };\n}\n\nexport function sortNotes(notes: Note[]): Note[] {\n  return [...notes].sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.updatedAt - a.updatedAt);\n}\n\nexport function noteTitle(n: Note): string {\n  return n.title.trim() || n.body.trim().split(\"\\n\")[0] || \"Untitled\";\n}\n\nexport function formatWhen(ts: number, now = Date.now()): string {\n  const d = new Date(ts);\n  const sameDay = new Date(now).toDateString() === d.toDateString();\n  if (sameDay) return d.toLocaleTimeString(\"en-US\", { hour: \"numeric\", minute: \"2-digit\" });\n  const days = Math.floor((now - ts) / 86_400_000);\n  if (days < 7) return d.toLocaleDateString(\"en-US\", { weekday: \"long\" });\n  return d.toLocaleDateString(\"en-US\", { month: \"short\", day: \"numeric\" });\n}\n\nexport function sampleNotes(): Note[] {\n  const now = Date.now();\n  const h = 3_600_000;\n  return [\n    { id: \"n1\", title: \"Weekend market list\", body: \"Sourdough\\nTomatoes (the striped ones)\\nGoat cheese\\nFlowers for the table\", pinned: true, updatedAt: now - 2 * h },\n    { id: \"n2\", title: \"Book club: next picks\", body: \"Tomorrow, and Tomorrow, and Tomorrow — vote by Friday.\\nAlso suggested: Piranesi, The Overstory.\", pinned: false, updatedAt: now - 26 * h },\n    { id: \"n3\", title: \"Trip to Lisbon\", body: \"Tram 28 early, before the queues. Pastéis in Belém. Sunset at Miradouro da Senhora do Monte.\", pinned: false, updatedAt: now - 3 * 24 * h },\n    { id: \"n4\", title: \"Ideas for the garden\", body: \"Move the rosemary to the sunny corner. Try a raised bed for herbs.\", pinned: false, updatedAt: now - 9 * 24 * h },\n  ];\n}\n",
    "src/screens/NoteEditor.tsx": "import { KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { formatWhen, type Note } from \"../notes\";\nimport { colors, space } from \"../theme\";\n\n/** Edits save as you type; Back returns to the list (empty notes are dropped there). */\nexport function NoteEditor({ note, onChange, onBack, onDelete }: { note: Note; onChange: (patch: Partial<Note>) => void; onBack: () => void; onDelete: () => void }) {\n  const insets = useSafeAreaInsets();\n  return (\n    <KeyboardAvoidingView style={styles.screen} behavior={Platform.OS === \"ios\" ? \"padding\" : undefined}>\n      <View style={[styles.toolbar, { paddingTop: insets.top + space.sm }]}>\n        <Pressable onPress={onBack} accessibilityRole=\"button\" accessibilityLabel=\"Back to notes\" hitSlop={8} style={styles.back}>\n          <Ionicons name=\"chevron-back\" size={24} color={colors.accent} />\n          <Text style={styles.backText}>Notes</Text>\n        </Pressable>\n        <View style={styles.actions}>\n          <Pressable onPress={() => onChange({ pinned: !note.pinned })} accessibilityRole=\"button\" accessibilityLabel={note.pinned ? \"Unpin note\" : \"Pin note\"} accessibilityState={{ selected: note.pinned }} hitSlop={8} style={styles.icon}>\n            <Ionicons name={note.pinned ? \"pin\" : \"pin-outline\"} size={22} color={colors.accent} />\n          </Pressable>\n          <Pressable onPress={onDelete} accessibilityRole=\"button\" accessibilityLabel=\"Delete note\" hitSlop={8} style={styles.icon}>\n            <Ionicons name=\"trash-outline\" size={22} color={colors.accent} />\n          </Pressable>\n        </View>\n      </View>\n      <ScrollView contentContainerStyle={[styles.body, { paddingBottom: insets.bottom + space.xxl }]} keyboardShouldPersistTaps=\"handled\">\n        <Text style={styles.when}>Edited {formatWhen(note.updatedAt)}</Text>\n        <TextInput value={note.title} onChangeText={(title) => onChange({ title })} placeholder=\"Title\" placeholderTextColor={colors.faint} style={styles.title} accessibilityLabel=\"Note title\" />\n        <TextInput\n          value={note.body}\n          onChangeText={(body) => onChange({ body })}\n          placeholder=\"Start writing…\"\n          placeholderTextColor={colors.faint}\n          style={styles.text}\n          multiline\n          textAlignVertical=\"top\"\n          accessibilityLabel=\"Note text\"\n          autoFocus={!note.title && !note.body}\n        />\n      </ScrollView>\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.surface },\n  toolbar: { flexDirection: \"row\", alignItems: \"center\", justifyContent: \"space-between\", paddingHorizontal: space.sm, paddingBottom: space.sm },\n  back: { flexDirection: \"row\", alignItems: \"center\", paddingVertical: space.xs },\n  backText: { fontSize: 17, color: colors.accent },\n  actions: { flexDirection: \"row\", gap: space.sm },\n  icon: { padding: space.sm },\n  body: { paddingHorizontal: space.xl, gap: space.sm },\n  when: { fontSize: 12, color: colors.faint, textAlign: \"center\" },\n  title: { fontSize: 26, fontWeight: \"700\", color: colors.text, paddingVertical: space.sm },\n  text: { fontSize: 17, lineHeight: 26, color: colors.text, minHeight: 320 },\n});\n",
    "src/screens/NotesList.tsx": "import { useMemo, useState } from \"react\";\nimport { FlatList, Pressable, StyleSheet, Text, TextInput, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { formatWhen, noteTitle, sortNotes, type Note } from \"../notes\";\nimport { colors, radius, space } from \"../theme\";\n\nexport function NotesList({ notes, onOpen, onCreate }: { notes: Note[]; onOpen: (id: string) => void; onCreate: () => void }) {\n  const insets = useSafeAreaInsets();\n  const [query, setQuery] = useState(\"\");\n  const visible = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return sortNotes(notes).filter((n) => !q || `${n.title}\\n${n.body}`.toLowerCase().includes(q));\n  }, [notes, query]);\n\n  return (\n    <View style={styles.screen}>\n      <FlatList\n        data={visible}\n        keyExtractor={(n) => n.id}\n        contentContainerStyle={[styles.list, { paddingTop: insets.top + space.lg, paddingBottom: insets.bottom + 110 }]}\n        ListHeaderComponent={\n          <View style={styles.header}>\n            <Text style={styles.title} accessibilityRole=\"header\">\n              Notes\n            </Text>\n            <Text style={styles.count}>\n              {notes.length} {notes.length === 1 ? \"note\" : \"notes\"}\n            </Text>\n            <View style={styles.search}>\n              <Ionicons name=\"search\" size={18} color={colors.muted} />\n              <TextInput value={query} onChangeText={setQuery} placeholder=\"Search notes\" placeholderTextColor={colors.faint} style={styles.searchInput} accessibilityLabel=\"Search notes\" />\n            </View>\n          </View>\n        }\n        ListEmptyComponent={\n          <View style={styles.empty}>\n            <Ionicons name=\"document-text-outline\" size={40} color={colors.faint} />\n            <Text style={styles.emptyText}>{query ? `Nothing matches “${query}”.` : \"No notes yet. Tap + to write one.\"}</Text>\n          </View>\n        }\n        renderItem={({ item }) => (\n          <Pressable onPress={() => onOpen(item.id)} accessibilityRole=\"button\" style={({ pressed }) => [styles.card, pressed && { backgroundColor: colors.accentSoft }]}>\n            <View style={styles.cardTop}>\n              <Text style={styles.cardTitle} numberOfLines={1}>\n                {noteTitle(item)}\n              </Text>\n              {item.pinned ? <Ionicons name=\"pin\" size={14} color={colors.accent} accessibilityLabel=\"Pinned\" /> : null}\n            </View>\n            <Text style={styles.cardBody} numberOfLines={2}>\n              {item.body.replace(/\\n+/g, \" · \") || \"No text\"}\n            </Text>\n            <Text style={styles.cardWhen}>{formatWhen(item.updatedAt)}</Text>\n          </Pressable>\n        )}\n      />\n      <Pressable onPress={onCreate} accessibilityRole=\"button\" accessibilityLabel=\"New note\" style={({ pressed }) => [styles.fab, { bottom: insets.bottom + space.xl }, pressed && { transform: [{ scale: 0.95 }] }]}>\n        <Ionicons name=\"add\" size={28} color=\"#ffffff\" />\n      </Pressable>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: { flex: 1, backgroundColor: colors.background },\n  list: { paddingHorizontal: space.lg, gap: space.sm },\n  header: { gap: space.xs, marginBottom: space.md },\n  title: { fontSize: 34, fontWeight: \"700\", color: colors.text, letterSpacing: -0.7 },\n  count: { fontSize: 14, color: colors.muted },\n  search: { marginTop: space.md, flexDirection: \"row\", alignItems: \"center\", gap: space.sm, backgroundColor: colors.surface, borderRadius: radius.md, borderWidth: StyleSheet.hairlineWidth, borderColor: colors.border, paddingHorizontal: space.md },\n  searchInput: { flex: 1, paddingVertical: space.md, fontSize: 15, color: colors.text },\n  card: { backgroundColor: colors.surface, borderRadius: radius.md, padding: space.lg, gap: 4, borderWidth: StyleSheet.hairlineWidth, borderColor: colors.border },\n  cardTop: { flexDirection: \"row\", alignItems: \"center\", gap: space.sm },\n  cardTitle: { flex: 1, fontSize: 16, fontWeight: \"600\", color: colors.text },\n  cardBody: { fontSize: 14, lineHeight: 20, color: colors.muted },\n  cardWhen: { fontSize: 12, color: colors.faint, marginTop: 2 },\n  empty: { alignItems: \"center\", gap: space.md, paddingVertical: space.xxl },\n  emptyText: { color: colors.muted, fontSize: 15 },\n  fab: { position: \"absolute\", right: space.xl, width: 58, height: 58, borderRadius: 29, backgroundColor: colors.accent, alignItems: \"center\", justifyContent: \"center\", boxShadow: \"0px 6px 16px rgba(120, 53, 15, 0.3)\" },\n});\n",
    "src/theme.ts": "export const colors = {\n  background: \"#fbfaf8\",\n  surface: \"#ffffff\",\n  text: \"#1f1a12\",\n  muted: \"#6f6656\",\n  faint: \"#b3aa9a\",\n  border: \"#ece4d3\",\n  accent: \"#b45309\",\n  accentSoft: \"#fbf1e2\",\n};\n\nexport const space = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 };\nexport const radius = { sm: 8, md: 14, lg: 20, pill: 999 };\n",
    "src/useStoredState.ts": "import { useEffect, useRef, useState } from \"react\";\nimport AsyncStorage from \"@react-native-async-storage/async-storage\";\n\n/**\n * useState that is saved with AsyncStorage (device storage on iOS/Android, localStorage on the\n * web). `ready` is false until the saved value has been read.\n */\nexport function useStoredState<T>(key: string, initial: () => T) {\n  const [value, setValue] = useState<T>(initial);\n  const [ready, setReady] = useState(false);\n  const loaded = useRef(false);\n\n  useEffect(() => {\n    let cancelled = false;\n    AsyncStorage.getItem(key)\n      .then((raw) => {\n        if (!cancelled && raw) setValue(JSON.parse(raw) as T);\n      })\n      .catch(() => {})\n      .finally(() => {\n        loaded.current = true;\n        if (!cancelled) setReady(true);\n      });\n    return () => {\n      cancelled = true;\n    };\n  }, [key]);\n\n  useEffect(() => {\n    if (!loaded.current) return;\n    AsyncStorage.setItem(key, JSON.stringify(value)).catch(() => {});\n  }, [key, value]);\n\n  return [value, setValue, ready] as const;\n}\n",
  },
  "expo-starter": {
    "App.tsx": "import { useState } from \"react\";\nimport { StyleSheet, View } from \"react-native\";\nimport { StatusBar } from \"expo-status-bar\";\nimport { SafeAreaProvider } from \"react-native-safe-area-context\";\nimport { TabBar, type TabId } from \"./src/components/TabBar\";\nimport { HomeScreen } from \"./src/screens/HomeScreen\";\nimport { ExploreScreen } from \"./src/screens/ExploreScreen\";\nimport { ProfileScreen } from \"./src/screens/ProfileScreen\";\nimport { colors } from \"./src/theme\";\n\n/**\n * The app shell: one screen at a time above a bottom tab bar. Navigation is plain React state, so\n * adding a screen means adding a tab in src/components/TabBar.tsx and a branch below.\n */\nexport default function App() {\n  const [tab, setTab] = useState<TabId>(\"home\");\n  return (\n    <SafeAreaProvider>\n      <View style={styles.root}>\n        <View style={styles.screen}>\n          {tab === \"home\" ? <HomeScreen onExplore={() => setTab(\"explore\")} /> : tab === \"explore\" ? <ExploreScreen /> : <ProfileScreen />}\n        </View>\n        <TabBar active={tab} onChange={setTab} />\n      </View>\n      <StatusBar style=\"dark\" />\n    </SafeAreaProvider>\n  );\n}\n\nconst styles = StyleSheet.create({\n  root: { flex: 1, backgroundColor: colors.background },\n  screen: { flex: 1 },\n});\n",
    "src/components/Screen.tsx": "import type { ReactNode } from \"react\";\nimport { ScrollView, StyleSheet, Text, View } from \"react-native\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { colors, space, type } from \"../theme\";\n\n/** A scrolling screen with a large title that clears the status bar and notch. */\nexport function Screen({ title, subtitle, children }: { title: string; subtitle?: string; children: ReactNode }) {\n  const insets = useSafeAreaInsets();\n  return (\n    <ScrollView style={styles.scroll} contentContainerStyle={[styles.content, { paddingTop: insets.top + space.lg }]}>\n      <View style={styles.header}>\n        {subtitle ? <Text style={type.caption}>{subtitle}</Text> : null}\n        <Text style={type.title} accessibilityRole=\"header\">\n          {title}\n        </Text>\n      </View>\n      {children}\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  scroll: { flex: 1, backgroundColor: colors.background },\n  content: { paddingHorizontal: space.lg, paddingBottom: space.xxl, gap: space.lg },\n  header: { gap: 2, marginBottom: space.xs },\n});\n",
    "src/components/TabBar.tsx": "import type { ComponentProps } from \"react\";\nimport { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { colors, space } from \"../theme\";\n\nexport type TabId = \"home\" | \"explore\" | \"profile\";\ntype IconName = ComponentProps<typeof Ionicons>[\"name\"];\n\nconst TABS: { id: TabId; label: string; icon: IconName; activeIcon: IconName }[] = [\n  { id: \"home\", label: \"Home\", icon: \"home-outline\", activeIcon: \"home\" },\n  { id: \"explore\", label: \"Explore\", icon: \"compass-outline\", activeIcon: \"compass\" },\n  { id: \"profile\", label: \"Profile\", icon: \"person-outline\", activeIcon: \"person\" },\n];\n\nexport function TabBar({ active, onChange }: { active: TabId; onChange: (tab: TabId) => void }) {\n  const insets = useSafeAreaInsets();\n  return (\n    <View style={[styles.bar, { paddingBottom: Math.max(insets.bottom, space.sm) }]} accessibilityRole=\"tablist\">\n      {TABS.map((t) => {\n        const selected = t.id === active;\n        return (\n          <Pressable\n            key={t.id}\n            onPress={() => onChange(t.id)}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected }}\n            accessibilityLabel={t.label}\n            style={({ pressed }) => [styles.tab, pressed && styles.pressed]}\n          >\n            <Ionicons name={selected ? t.activeIcon : t.icon} size={24} color={selected ? colors.accent : colors.muted} />\n            <Text style={[styles.label, selected && styles.labelActive]}>{t.label}</Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  bar: {\n    flexDirection: \"row\",\n    backgroundColor: colors.surface,\n    borderTopWidth: StyleSheet.hairlineWidth,\n    borderTopColor: colors.border,\n    paddingTop: space.sm,\n  },\n  tab: { flex: 1, alignItems: \"center\", gap: 2, paddingVertical: space.xs },\n  pressed: { opacity: 0.6 },\n  label: { fontSize: 11, fontWeight: \"500\", color: colors.muted },\n  labelActive: { color: colors.accent },\n});\n",
    "src/screens/ExploreScreen.tsx": "import { useMemo, useState, type ComponentProps } from \"react\";\nimport { StyleSheet, Text, TextInput, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { Screen } from \"../components/Screen\";\nimport { colors, radius, space, type } from \"../theme\";\n\ntype Item = { name: string; detail: string; icon: ComponentProps<typeof Ionicons>[\"name\"] };\n\nconst BLOCKS: Item[] = [\n  { name: \"View\", detail: \"The box every layout is made of. Flexbox, column by default.\", icon: \"square-outline\" },\n  { name: \"Text\", detail: \"All text must sit inside a Text element.\", icon: \"text-outline\" },\n  { name: \"Pressable\", detail: \"Anything tappable, with pressed and focus states.\", icon: \"hand-left-outline\" },\n  { name: \"ScrollView\", detail: \"A scrolling container for short content.\", icon: \"swap-vertical-outline\" },\n  { name: \"FlatList\", detail: \"Long or endless lists, rendered lazily.\", icon: \"list-outline\" },\n  { name: \"TextInput\", detail: \"Single and multi-line text fields.\", icon: \"create-outline\" },\n  { name: \"Image\", detail: \"Local or remote images with resize modes.\", icon: \"image-outline\" },\n  { name: \"Switch\", detail: \"An on/off toggle that follows the platform style.\", icon: \"toggle-outline\" },\n  { name: \"StyleSheet\", detail: \"Typed style objects instead of CSS classes.\", icon: \"color-palette-outline\" },\n];\n\nexport function ExploreScreen() {\n  const [query, setQuery] = useState(\"\");\n  const results = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return q ? BLOCKS.filter((b) => `${b.name} ${b.detail}`.toLowerCase().includes(q)) : BLOCKS;\n  }, [query]);\n\n  return (\n    <Screen title=\"Explore\" subtitle=\"React Native building blocks\">\n      <View style={styles.search}>\n        <Ionicons name=\"search\" size={18} color={colors.muted} />\n        <TextInput value={query} onChangeText={setQuery} placeholder=\"Search components\" placeholderTextColor={colors.muted} style={styles.input} accessibilityLabel=\"Search components\" autoCorrect={false} />\n      </View>\n      <View style={styles.list}>\n        {results.map((b) => (\n          <View key={b.name} style={styles.item}>\n            <View style={styles.icon}>\n              <Ionicons name={b.icon} size={20} color={colors.accent} />\n            </View>\n            <View style={styles.itemText}>\n              <Text style={styles.itemName}>{b.name}</Text>\n              <Text style={type.caption}>{b.detail}</Text>\n            </View>\n          </View>\n        ))}\n        {results.length === 0 ? <Text style={[type.caption, styles.empty]}>Nothing matches “{query}”.</Text> : null}\n      </View>\n    </Screen>\n  );\n}\n\nconst styles = StyleSheet.create({\n  search: {\n    flexDirection: \"row\",\n    alignItems: \"center\",\n    gap: space.sm,\n    backgroundColor: colors.surface,\n    borderRadius: radius.md,\n    borderWidth: StyleSheet.hairlineWidth,\n    borderColor: colors.border,\n    paddingHorizontal: space.md,\n  },\n  input: { flex: 1, paddingVertical: space.md, fontSize: 15, color: colors.text },\n  list: { gap: space.sm },\n  item: { flexDirection: \"row\", gap: space.md, alignItems: \"center\", backgroundColor: colors.surface, borderRadius: radius.md, padding: space.md },\n  icon: { width: 40, height: 40, borderRadius: radius.sm, backgroundColor: colors.accentSoft, alignItems: \"center\", justifyContent: \"center\" },\n  itemText: { flex: 1, gap: 2 },\n  itemName: { ...type.body, fontWeight: \"600\" },\n  empty: { textAlign: \"center\", paddingVertical: space.xl },\n});\n",
    "src/screens/HomeScreen.tsx": "import { useState } from \"react\";\nimport { Pressable, StyleSheet, Text, View } from \"react-native\";\nimport { Ionicons } from \"@expo/vector-icons\";\nimport { Screen } from \"../components/Screen\";\nimport { colors, radius, space, type } from \"../theme\";\n\nconst STEPS = [\n  { id: \"edit\", title: \"Change this screen\", detail: \"Open src/screens/HomeScreen.tsx and edit the text.\" },\n  { id: \"ask\", title: \"Describe a feature\", detail: \"Ask Codexa for a new screen, a form or a list.\" },\n  { id: \"phone\", title: \"Open it on your phone\", detail: \"Preview → Your Device, then scan with Expo Go.\" },\n  { id: \"publish\", title: \"Publish the web version\", detail: \"Publish builds the web app and gives it a URL.\" },\n];\n\nexport function HomeScreen({ onExplore }: { onExplore: () => void }) {\n  const [done, setDone] = useState<Record<string, boolean>>({ edit: false });\n  const count = STEPS.filter((s) => done[s.id]).length;\n\n  return (\n    <Screen title=\"Your new app\" subtitle=\"Welcome\">\n      <View style={styles.hero}>\n        <Text style={styles.heroTitle}>Built with React Native and Expo</Text>\n        <Text style={styles.heroBody}>The same code runs on iOS, Android and the web. Everything you see is a View, Text or Pressable.</Text>\n        <Pressable onPress={onExplore} accessibilityRole=\"button\" style={({ pressed }) => [styles.heroButton, pressed && { opacity: 0.85 }]}>\n          <Text style={styles.heroButtonText}>Explore the building blocks</Text>\n          <Ionicons name=\"arrow-forward\" size={16} color={colors.accent} />\n        </Pressable>\n      </View>\n\n      <View style={styles.section}>\n        <View style={styles.sectionHeader}>\n          <Text style={type.heading}>Getting started</Text>\n          <Text style={type.caption}>\n            {count} of {STEPS.length} done\n          </Text>\n        </View>\n        <View style={styles.progressTrack}>\n          <View style={[styles.progressFill, { width: `${(count / STEPS.length) * 100}%` }]} />\n        </View>\n        <View style={styles.card}>\n          {STEPS.map((s, i) => {\n            const checked = Boolean(done[s.id]);\n            return (\n              <Pressable\n                key={s.id}\n                onPress={() => setDone((d) => ({ ...d, [s.id]: !checked }))}\n                accessibilityRole=\"checkbox\"\n                accessibilityState={{ checked }}\n                style={({ pressed }) => [styles.row, i > 0 && styles.rowDivider, pressed && { backgroundColor: colors.background }]}\n              >\n                <Ionicons name={checked ? \"checkmark-circle\" : \"ellipse-outline\"} size={24} color={checked ? colors.success : colors.border} />\n                <View style={styles.rowText}>\n                  <Text style={[styles.rowTitle, checked && styles.rowTitleDone]}>{s.title}</Text>\n                  <Text style={type.caption}>{s.detail}</Text>\n                </View>\n              </Pressable>\n            );\n          })}\n        </View>\n      </View>\n    </Screen>\n  );\n}\n\nconst styles = StyleSheet.create({\n  hero: { backgroundColor: colors.accent, borderRadius: radius.lg, padding: space.xl, gap: space.sm },\n  heroTitle: { color: \"#ffffff\", fontSize: 20, fontWeight: \"700\", letterSpacing: -0.3 },\n  heroBody: { color: \"#dbe4fb\", fontSize: 15, lineHeight: 22 },\n  heroButton: {\n    marginTop: space.sm,\n    alignSelf: \"flex-start\",\n    flexDirection: \"row\",\n    alignItems: \"center\",\n    gap: space.xs,\n    backgroundColor: \"#ffffff\",\n    borderRadius: radius.pill,\n    paddingHorizontal: space.lg,\n    paddingVertical: 10,\n  },\n  heroButtonText: { color: colors.accent, fontWeight: \"600\", fontSize: 14 },\n  section: { gap: space.md },\n  sectionHeader: { flexDirection: \"row\", justifyContent: \"space-between\", alignItems: \"baseline\" },\n  progressTrack: { height: 6, borderRadius: radius.pill, backgroundColor: colors.border, overflow: \"hidden\" },\n  progressFill: { height: 6, borderRadius: radius.pill, backgroundColor: colors.success },\n  card: { backgroundColor: colors.surface, borderRadius: radius.md, borderWidth: StyleSheet.hairlineWidth, borderColor: colors.border, overflow: \"hidden\" },\n  row: { flexDirection: \"row\", alignItems: \"center\", gap: space.md, padding: space.lg },\n  rowDivider: { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border },\n  rowText: { flex: 1, gap: 2 },\n  rowTitle: { ...type.body, fontWeight: \"600\" },\n  rowTitleDone: { color: colors.muted, textDecorationLine: \"line-through\" },\n});\n",
    "src/screens/ProfileScreen.tsx": "import { useState } from \"react\";\nimport { StyleSheet, Switch, Text, View } from \"react-native\";\nimport { Screen } from \"../components/Screen\";\nimport { colors, radius, space, type } from \"../theme\";\n\nexport function ProfileScreen() {\n  const [settings, setSettings] = useState({ reminders: true, weekly: false, haptics: true });\n  const toggle = (key: keyof typeof settings) => setSettings((s) => ({ ...s, [key]: !s[key] }));\n\n  return (\n    <Screen title=\"Profile\">\n      <View style={styles.person}>\n        <View style={styles.avatar}>\n          <Text style={styles.initials}>AR</Text>\n        </View>\n        <View>\n          <Text style={type.heading}>Alex Rivera</Text>\n          <Text style={type.caption}>alex@example.com</Text>\n        </View>\n      </View>\n\n      <Text style={styles.groupLabel}>Notifications</Text>\n      <View style={styles.card}>\n        <Row label=\"Daily reminders\" value={settings.reminders} onChange={() => toggle(\"reminders\")} />\n        <Row label=\"Weekly summary\" value={settings.weekly} onChange={() => toggle(\"weekly\")} divider />\n        <Row label=\"Haptic feedback\" value={settings.haptics} onChange={() => toggle(\"haptics\")} divider />\n      </View>\n\n      <Text style={[type.caption, styles.footnote]}>Settings are kept in memory. Ask Codexa to save them with AsyncStorage.</Text>\n    </Screen>\n  );\n}\n\nfunction Row({ label, value, onChange, divider }: { label: string; value: boolean; onChange: () => void; divider?: boolean }) {\n  return (\n    <View style={[styles.row, divider && styles.divider]}>\n      <Text style={type.body}>{label}</Text>\n      <Switch value={value} onValueChange={onChange} trackColor={{ true: colors.accent, false: colors.border }} thumbColor=\"#ffffff\" accessibilityLabel={label} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  person: { flexDirection: \"row\", alignItems: \"center\", gap: space.lg, backgroundColor: colors.surface, borderRadius: radius.md, padding: space.lg },\n  avatar: { width: 56, height: 56, borderRadius: 28, backgroundColor: colors.accentSoft, alignItems: \"center\", justifyContent: \"center\" },\n  initials: { fontSize: 18, fontWeight: \"700\", color: colors.accent },\n  groupLabel: { ...type.caption, textTransform: \"uppercase\", letterSpacing: 0.6, marginBottom: -space.sm },\n  card: { backgroundColor: colors.surface, borderRadius: radius.md, overflow: \"hidden\" },\n  row: { flexDirection: \"row\", alignItems: \"center\", justifyContent: \"space-between\", paddingHorizontal: space.lg, paddingVertical: space.md },\n  divider: { borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: colors.border },\n  footnote: { textAlign: \"center\" },\n});\n",
    "src/theme.ts": "/** Colours, spacing and radii used across the app. Change the accent here to rebrand it. */\nexport const colors = {\n  background: \"#f7f7f5\",\n  surface: \"#ffffff\",\n  text: \"#111827\",\n  muted: \"#6b7280\",\n  border: \"#e5e7eb\",\n  accent: \"#1d4ed8\",\n  accentSoft: \"#e8eefc\",\n  success: \"#047857\",\n};\n\nexport const space = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 };\n\nexport const radius = { sm: 8, md: 12, lg: 16, pill: 999 };\n\nexport const type = {\n  title: { fontSize: 28, fontWeight: \"700\" as const, letterSpacing: -0.5, color: colors.text },\n  heading: { fontSize: 17, fontWeight: \"600\" as const, color: colors.text },\n  body: { fontSize: 15, lineHeight: 22, color: colors.text },\n  caption: { fontSize: 13, color: colors.muted },\n};\n",
  },
};
